# Export only the ANI module entry. _init/_fini and other symbols are kept
# local to avoid duplicate excepted symbols across modules. the CFI symbols
# (e.g. __cfi_check) are still excepted by sanitizer-injected
# build/config/sanitizers/cfi.versionscript.

1.0 {
  global:
    ANI_Constructor;

  local:
    *;
 };